item.aggregated_output:
package scan

import (
	"github.com/aquasecurity/fanal/analyzer"
	"github.com/future-architect/vuls/models"

	trivyTypes "github.com/aquasecurity/trivy/pkg/types"
)

func convertLibWithScanner(result *analyzer.AnalysisResult) ([]models.LibraryScanner, error) {
	scanners := []models.LibraryScanner{}
	for _, app := range result.Applications {
		libs := []trivyTypes.Library{}
		for _, lib := range app.Libraries {
			libs = append(libs, trivyTypes.Library{
				Name:    lib.Library.Name,
				Version: lib.Library.Version,
			})
		}
		scanners = append(scanners, models.LibraryScanner{
			Path: app.FilePath,
			Libs: libs,
		})
	}
	return scanners, nil
}

